#[test]
fn nested_tool_use_joins_last_of_adjacent_assistant_run() {
    let items = vec![
        user("q"),
        nested(vec![use_part("t1")]),
        nested(vec![use_part("t2")]),
        result("t2"),
        nested(vec![use_part("t3")]),
        result("t1"),
        result("t3"),
